-- +goose Up
CREATE EXTENSION IF NOT EXISTS citext;

-- IDs are UUIDv7 generated by the application (sortable by creation time).
CREATE TABLE users (
    id            uuid PRIMARY KEY,
    email         citext NOT NULL UNIQUE CHECK (char_length(email) <= 254),
    username      citext NOT NULL UNIQUE CHECK (char_length(username) BETWEEN 2 AND 32),
    display_name  text   NOT NULL CHECK (char_length(display_name) BETWEEN 1 AND 32),
    password_hash text   NOT NULL,
    created_at    timestamptz NOT NULL DEFAULT now(),
    updated_at    timestamptz NOT NULL DEFAULT now()
);

-- One row per signed-in device. A session is a refresh-token family:
-- every refresh rotates refresh_hash, and presenting a stale token outside
-- the grace window revokes the whole session (see docs/adr/0009-auth.md).
CREATE TABLE sessions (
    id                uuid PRIMARY KEY,
    user_id           uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    refresh_hash      bytea NOT NULL,
    prev_refresh_hash bytea,
    rotated_at        timestamptz NOT NULL DEFAULT now(),
    device            text NOT NULL DEFAULT '' CHECK (char_length(device) <= 128),
    ip                inet,
    created_at        timestamptz NOT NULL DEFAULT now(),
    last_used_at      timestamptz NOT NULL DEFAULT now(),
    expires_at        timestamptz NOT NULL,
    revoked_at        timestamptz,
    revoke_reason     text
);

CREATE INDEX sessions_user_active ON sessions (user_id) WHERE revoked_at IS NULL;

-- +goose Down
DROP TABLE sessions;
DROP TABLE users;
